// Display connection test results
const connectionResult = $('Test MySQL Connection').first().json;
const tableResult = $('Check Database Tables').first().json;

console.log('=== MySQL Connection Test Results ===');
console.log(`Message: ${connectionResult.message}`);
console.log(`Database: ${connectionResult.database_name}`);
console.log(`Current Time: ${connectionResult.current_time}`);
console.log(`Tables in Database: ${tableResult.table_count}`);
console.log('Connection Status: SUCCESS');

return {
  json: {
    connection_status: 'SUCCESS',
    database: connectionResult.database_name,
    timestamp: connectionResult.current_time,
    message: connectionResult.message,
    existing_tables: tableResult.table_count
  }
};
